    GrammaticalTerm term2 = mock(GrammaticalTerm.class);

    @Test
    public void defaultConstructorTest() {
        GrammaticalTermMapImpl<GrammaticalTerm> map = new GrammaticalTermMapImpl<>();
        assertNotNull(map);
    }

